import{b as a,O as t,g as o,j as r}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"趣说战国250年","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/warring-states/index.md","filePath":"读书感悟/电子书架/46.趣说战国250年.md","lastUpdated":1781614933000}'),i={name:"reading/digital/warring-states/index.md"};function d(l,e,n,c,s,_){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="趣说战国250年" tabindex="-1">趣说战国250年 <a class="header-anchor" href="#趣说战国250年" aria-label="Permalink to &quot;趣说战国250年&quot;">​</a></h1><p><code>关丁</code> <code>历史读物</code></p><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 能人</p><p>📌 “吴起这家伙，贪图功名利禄，而且好色；但要说到带兵打仗，却没几个人比得过他，哪怕是司马穰苴这样的名将也不是他的对手。”</p></blockquote><blockquote><p>💭 我第一眼也看成了二百五……</p><p>📌 一千人的老大，则叫“二五百主”</p></blockquote><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><blockquote><p>比较有意思的是春秋的时候打仗都是礼尚往来，你打我一下，我打你一下，点到为止，等级制度还在，打仗的时候遇到等级高的敌方首领在打之前还会先去敬个礼，然后再回去开打，那个时候礼乐还没有完全崩坏。</p></blockquote><blockquote><p>到了战国就不一样了，谁来了都不行，就是要打，战场的规模也越来越大，战争动辄都是几十万的兵力，很难想象那个年代的战争是多残酷和百姓的生活是怎么样的。当然也有很多意难平的事情，比如白起、李牧，打仗一把好手，最后被自己人给坑杀了，真的是一言难尽。</p></blockquote>',8)])])}const h=a(i,[["render",d]]);export{u as __pageData,h as default};
